);

// LastUsed recently.
await queryCheck(
  {
    folderId: rootFolder.id,
    lastUsed: { recent: true },
    sort: "lastUsed",
    limit: browser.folders.DEFAULT_MOST_RECENT_LIMIT,
  },
  ["OtherTest"]
);
await queryCheck(
  {
    folderId: rootFolder.id,
    lastUsed: { recent: true },
    sort: "lastUsed",
  },
  ["OtherTest", "InfoTest"]
);
await queryCheck(
  {
    folderId: rootFolder.id,
    lastUsed: { recent: true },
    sort: "name",
  },
  ["InfoTest", "OtherTest"]
);
await queryCheck(
  { folderId: rootFolder.id, lastUsed: { recent: false } },
  expectedAccountFolders.filter(
    f => !["InfoTest", "OtherTest"].includes(f)
  )
);
